return ['domain'=>'wpml-import','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'ru_RU','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'Универсальный плагин для экспорта и импорта многоязычного контента.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'Триггер импорта больше не принимает ключ в URL. Отправьте его в теле POST.','Method Not Allowed'=>'Метод не поддерживается','Unauthorized'=>'Не авторизовано','No items to process'=>'Нет элементов для обработки','No Content'=>'Нет содержимого','Import process completed'=>'Процесс импорта завершен','Success'=>'Успешно','Import process failed'=>'Ошибка процесса импорта','Internal Server Error'=>'Внутренняя ошибка сервера','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: %2$d элемент не удалось обработать, он был пропущен.' . "\0" . '%1$s: %2$d элемента не удалось обработать, они были пропущены.' . "\0" . '%1$s: %2$d элементов не удалось обработать, они были пропущены.','Cleaning Up Post Data'=>'Очистка данных записей','Removing temporary and import-related post meta data.'=>'Удаление временных и связанных с импортом метаданных записей.','Cleaning Up Term Data'=>'Очистка данных терминов','Removing temporary and import-related term meta data.'=>'Удаление временных и связанных с импортом метаданных терминов.','Connecting Post Image Attachments'=>'Связывание медиафайлов записей','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'Обновление ID миниатюр и галерей в переведенных записях, товарах и произвольных типах записей для их привязки к соответствующим переводам.','Connecting Inline Term Translations'=>'Связывание встроенных переводов терминов','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'Сканирование записей с одним термином таксономии для идентификации и связывания терминов, назначенных этим записям, с их переводами.','Deleting Obsolete Original Terms'=>'Удаление устаревших оригинальных терминов','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'Удаление оригинальных терминов, которые больше не нужны после создания дублей для терминов с одинаковыми именами. Проверка отсутствия связей записей с этими оригинальными терминами.','Duplicating Terms with Shared Names Across Languages'=>'Дублирование терминов с общими именами на разных языках','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'Создание дублей на правильном языке для терминов с одинаковыми именами на разных языках, но относящихся к записям на разных языках.','Fixing Imported Post Slugs'=>'Исправление ярлыков импортированных записей','Regenerating translated post slugs to prevent conflicts with the originals.'=>'Перегенерация ярлыков переведенных записей для предотвращения конфликтов с оригиналами.','Clearing Translations Cache'=>'Очистка кэша переводов','Invalidating the persistent cache so it can be regenerated.'=>'Инвалидация постоянного кэша для его последующей регенерации.','Marking Parent Terms for Connection'=>'Маркировка родительских терминов для связывания','Collecting parent terms to connect their translations in the next step.'=>'Сбор родительских терминов для связывания их переводов на следующем этапе.','Connecting Posts with Correct Term Translations'=>'Связывание записей с правильными переводами терминов','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'Обеспечение связи записей с терминами на правильном языке, особенно если у вас есть одинаковые названия терминов на разных языках.','Sending Posts for Automatic Translation'=>'Отправка записей на автоматический перевод','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'Создание заданий на автоматический перевод для записей, помеченных для автоперевода в экспортированных данных.','Setting Attachments\' Language'=>'Настройка языка медиафайлов','Assigning a language to imported attachments.'=>'Назначение языка импортированным медиафайлам.','Updating Final Post Status'=>'Обновление окончательного статуса записей','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'Установка статуса записи на основе поля «_wpml_import_after_process_post_status» из файла импорта (если оно предоставлено).','Identifying Inline Term Languages'=>'Определение языков встроенных терминов','Identifying and setting the language of terms created during post imports.'=>'Идентификация и настройка языка терминов, созданных во время импорта записей.','Setting Posts’ Language'=>'Настройка языка записей','Connecting posts to the default language and translations.'=>'Связывание записей с языком по умолчанию и переводами.','Setting Terms’ Language'=>'Настройка языка терминов','Connecting taxonomy terms to the default (original) language and translations.'=>'Связывание терминов таксономии с языком по умолчанию (оригиналом) и переводами.','Setting Parent Terms\' Language'=>'Настройка языка родительских терминов','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'Назначение языка родительским терминам таксономии, у которых он отсутствует, на основе языка, назначенного их дочерним элементам.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'Переносите свой многоязычный сайт? Не забудьте также установить %s на новом сайте перед импортом контента, чтобы мы могли восстановить все переводы.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'Переносите свой многоязычный магазин? С помощью %1$s и %2$s вы можете перенести переведенный контент на новый сайт, включая кросс-продажи, апсейлы и атрибуты товаров.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Переносите свой многоязычный магазин? Не забудьте установить %1$s и %2$s на новом сайте перед импортом контента, чтобы мы могли восстановить все переводы.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'Хотите импортировать свой многоязычный контент? Не забудьте установить %s на исходном сайте перед экспортом его содержимого, чтобы мы могли импортировать все переводы сюда.','Looking to import your multilingual content? Install %1$s on this site.'=>'Хотите импортировать свой многоязычный контент? Установите %1$s на этом сайте.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'Не забудьте также включить %2$s и %3$s в вашем исходном магазине перед экспортом его содержимого, чтобы мы могли импортировать все переводы сюда.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'Хотите импортировать свой многоязычный контент? Не забудьте включить %1$s и %2$s в вашем исходном магазине перед экспортом его содержимого, чтобы мы могли импортировать все переводы сюда.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'Переключиться на все языки','Linking Product Attribute Translations'=>'Связывание переводов атрибутов товаров','Connecting product attributes to their translations based on associated product variations.'=>'Связывание атрибутов товаров с их переводами на основе связанных вариаций товаров.','Updating Related Products On Translations'=>'Обновление сопутствующих товаров в переводах','Setting up-sells, cross-sells and grouped products references in the right language.'=>'Настройка ссылок на апсейлы, кросс-продажи и сгруппированные товары на правильном языке.','Importing Custom Attribute Labels'=>'Импорт ярлыков пользовательских атрибутов','Importing labels for product-specific (custom) attributes from the exported data.'=>'Импорт ярлыков для специфических (пользовательских) атрибутов товаров из экспортированных данных.','You are about to export all your products in all languages at once.'=>'Вы собираетесь экспортировать все свои товары на всех языках одновременно.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Не забудьте установить %1$s и %2$s на новом сайте перед импортом контента, чтобы мы могли восстановить все переводы.','You are about to export your products in %s.'=>'Вы собираетесь экспортировать свои товары на языке %s.','Registering Product Attributes'=>'Регистрация атрибутов товаров','Identifying and registering attributes created during product imports for translation.'=>'Идентификация и регистрация атрибутов, созданных во время импорта товаров, для перевода.','Identifying Product Attribute Languages'=>'Определение языков атрибутов товаров','Identifying and setting the language of attributes created during product imports.'=>'Идентификация и настройка языка атрибутов, созданных во время импорта товаров.','Export and Import'=>'Экспорт и импорт','I’m using the built-in %s export/import tool'=>'Я использую встроенный инструмент экспорта/импорта %s','I’m using %s plugin'=>'Я использую плагин %s','(%1$d/%2$d items)'=>'(%1$d/%2$d элементов)','%d skipped'=>'%d пропущено','(no items)'=>'(нет элементов)','Counting items...'=>'Подсчет элементов...','First, tell us how you’re going to create the content that you’ll be importing:'=>'Сначала скажите нам, как вы собираетесь создавать контент для импорта:','Continue'=>'Продолжить','I’m using %1$s and %2$s plugins'=>'Я использую плагины %1$s и %2$s','I’m using a different method to export from this site'=>'Я использую другой метод для экспорта с этого сайта','I’m exporting the content from this site'=>'Я экспортирую контент с этого сайта','I’m exporting the content from a different website or system'=>'Я экспортирую контент с другого сайта или из другой системы','Before importing, add language columns to your content'=>'Перед импортом добавьте в контент столбцы с языками','Make sure that your import file includes the following columns (custom fields) with language information:'=>'Убедитесь, что ваш файл импорта содержит следующие столбцы (произвольные поля) с информацией о языке:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: значение, одинаковое для всех переводов каждого элемента. В интернет-магазинах это часто артикул (SKU).','%s: The language code for each item.'=>'%s: код языка для каждого элемента.','And, you can include these two columns if needed:'=>'Также при необходимости вы можете включить эти два столбца:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: если этот элемент является переводом, установите для этого столбца код исходного языка. Если это не перевод, оставьте его пустым.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: установите значение «draft» (черновик) или «published» (опубликовано), чтобы определить статус публикации записи после настройки языков. Обычно это значение — «published».','Here is an example of importing two items, into your site’s languages (%s):'=>'Вот пример импорта двух элементов на языки вашего сайта (%s):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'После добавления столбцов с языками в файл многоязычного контента импортируйте его на свой сайт с помощью любого удобного плагина импорта.','Before importing, your content needs language information'=>'Перед импортом контенту необходима информация о языке','%s will add the necessary language information to your export.'=>'%s добавит необходимую информацию о языке в ваш экспорт.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'Импортируйте файл многоязычного контента на сайт с помощью любого удобного плагина импорта.','Use your favorite import plugin'=>'Используйте ваш любимый плагин импорта','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'После импорта контента информация о языке все еще может отображаться некорректно. Поэтому мы рекомендуем импортировать новый контент как черновики. Если вы импортируете обновления, вы можете оставить уже опубликованный контент опубликованным.','Return here, to %s, to set languages and connect translations'=>'Вернитесь сюда, в %s, чтобы настроить языки и связать переводы','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'Когда вы посетите эту страницу после импорта контента с информацией о языке, вы сможете запустить %s, чтобы применить языки и связать переводы.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'Уже импортировали, но все еще видите этот экран? %1$sУстранение неполадок %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'Как экспортировать и импортировать контент на нескольких языках','%s is ready to update your imported content'=>'%s готов обновить ваш импортированный контент','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'Отлично. Мы видим %1$d терминов и %2$d записей, которые импортированы и нуждаются в информации о языке.','Good job. We see %d terms that are imported and need language information.'=>'Отлично. Мы видим %d терминов, которые импортированы и нуждаются в информации о языке.','Good job. We see %d posts that are imported and need language information.'=>'Отлично. Мы видим %d записей, которые импортированы и нуждаются в информации о языке.','Run WPML Import'=>'Запустить WPML Import','Multilingual Import Complete'=>'Многоязычный импорт завершен']];